mapper.select:
SELECT s.orders_id as ordersId,s.user_id,COALESCE(t.name, l.name, st.name) as userName,sta.staff_id, sta.name as staffName,sta.location,s.status as status,s.create_time as createTime,s.update_time as updateTime FROM staff_orders s LEFT JOIN teacher t ON s.user_id = t.teacher_id LEFT JOIN logistics l ON s.user_id = l.logistics_id LEFT JOIN student st ON s.user_id = st.student_id LEFT JOIN staff sta ON s.staff_id = sta.staff_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}
